package com.ianblk.zianmobs.client;
import com.ianblk.zianmobs.*;
import java.nio.file.*;
import net.minecraft.client.Minecraft;
import net.minecraft.client.Screenshot;
import net.minecraft.client.CameraType;
import net.neoforged.neoforge.client.event.ClientTickEvent;
public final class CompanionSceneClient {
 private static final boolean FOCUS=Boolean.getBoolean("zianmobs.eyeFocus");private static final int[] FOCUS_STAGES={0,2,3,4,5,7,8,10,11,29,36,37,38,39};
 private static int ticks,stage=-1,bootTicks;private static String lastScreen="";private static volatile Throwable failure;
 public static void register(){if(Boolean.getBoolean("zianmobs.scene")&&!Boolean.getBoolean("zianmobs.attackScene")&&!Boolean.getBoolean("zianmobs.flightScene"))net.neoforged.neoforge.common.NeoForge.EVENT_BUS.addListener(CompanionSceneClient::tick);}
 private static void tick(ClientTickEvent.Post event){var mc=Minecraft.getInstance();if(mc.getOverlay()==null&&mc.screen!=null){String screen=mc.screen.getClass().getSimpleName();if(!lastScreen.equals(screen)){lastScreen=screen;ZianMobs.LOGGER.info("Scene waiting on {}: {}",screen,mc.screen.getTitle().getString());Screenshot.grab(mc.gameDirectory,"boot-"+screen+".png",mc.getMainRenderTarget(),c->{});}if(screen.equals("AccessibilityOnboardingScreen")){mc.options.onboardAccessibility=false;mc.options.save();mc.setScreen(new net.minecraft.client.gui.screens.TitleScreen());return;}if(screen.equals("TitleScreen")&&++bootTicks==40){mc.createWorldOpenFlows().openWorld("companions-scene",()->mc.stop());return;}}if(mc.level==null||mc.player==null||mc.getSingleplayerServer()==null||mc.getOverlay()!=null||mc.screen!=null)return;try{if(!mc.gameDirectory.getAbsolutePath().contains("mobs-scene-client"))throw new IllegalStateException("Wrong scene profile");if(failure!=null)throw new IllegalStateException("Server scene failed",failure);mc.options.hideGui=(FOCUS?FOCUS_STAGES[Math.max(0,stage)]:stage)<33;mc.options.setCameraType(CameraType.FIRST_PERSON);mc.options.fov().set(60);var server=mc.getSingleplayerServer();if(stage==-1){stage=0;ticks=0;server.execute(()->{try{CompanionScene.setup(server);}catch(Throwable ex){failure=ex;}});return;}if(FOCUS&&FOCUS_STAGES[stage]!=38)mc.options.keyUse.setDown(false);if(FOCUS&&FOCUS_STAGES[stage]==38){mc.options.keyUse.setDown(true);if(ticks==0)mc.gameMode.useItem(mc.player,net.minecraft.world.InteractionHand.OFF_HAND);}if(++ticks<60)return;if(FOCUS&&FOCUS_STAGES[stage]==38&&!mc.player.isUsingItem())throw new IllegalStateException("Gauntlet blocking did not reach the client");ticks=0;if(FOCUS&&FOCUS_STAGES[stage]>=37){boolean active=FOCUS_STAGES[stage]==38;if(TitanAbilities.awakened(mc.player)!=active)throw new IllegalStateException("Titan buff state did not sync to client");TitanVisualSmoke.check(mc.getItemRenderer().getModel(mc.player.getOffhandItem(),mc.level,mc.player,0),active);}Screenshot.grab(mc.gameDirectory,(FOCUS?"eyes-":"scene-")+(FOCUS?FOCUS_STAGES[stage]:stage)+".png",mc.getMainRenderTarget(),c->ZianMobs.LOGGER.info("Scene image {}",c.getString()));if(++stage>=(FOCUS?FOCUS_STAGES.length:CompanionScene.STAGES)){Files.writeString(mc.gameDirectory.toPath().resolve(FOCUS?"eyes-result.txt":"scene-result.txt"),(FOCUS?"PASS: shader comparison scene rendered with companion controls.\n":"PASS: all 29 companion models and Snowbone rendered, walking and shooting clips, live randomized support with chat, immediate 32 block withdrawal and local revocation in isolated scene.\n"));mc.stop();}else{int next=FOCUS?FOCUS_STAGES[stage]:stage;server.execute(()->{try{CompanionScene.stage(server,next);}catch(Throwable ex){failure=ex;}});}}catch(Throwable ex){ZianMobs.LOGGER.error("COMPANION-SCENE FAIL",ex);try{Files.writeString(mc.gameDirectory.toPath().resolve(FOCUS?"eyes-result.txt":"scene-result.txt"),"FAIL: "+ex);}catch(Exception ignored){}mc.stop();}}
}
